import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`fb-marketplace`,heroTitle:`Sell on Facebook Marketplace in minutes`,heroSubtitle:`Perplexity Computer researches your product, writes optimized listings, and prices them competitively — automatically.`,inputUrlCta:`List my product`,inputUrlPlaceholder:`www.facebook.com/marketplace/item`,inputUrlPrefill:`Go to {url} and analyze the product shown on this page. Research comparable listings on Facebook Marketplace and other resale platforms to determine competitive pricing. Then create an optimized Facebook Marketplace listing with: 1) A compelling title using high-traffic search keywords, 2) A detailed description highlighting key features, condition, and selling points, 3) A competitive price range based on current market data, 4) Suggested category and tags, 5) Tips for photos and posting time to maximize visibility.`,heroOverlaySteps:[`Analyzing your product page for details, specs, and condition`,`Researching comparable listings across Facebook Marketplace and resale platforms`,`Writing an SEO-optimized title, description, and pricing strategy`,`Listing copy, competitive pricing, and posting tips — ready to publish`],generatingSteps:[`Visiting {url} to extract product details, specs, and images`,`Designing an agent to research competitive pricing across Facebook Marketplace and resale platforms`,`Configuring listing optimization for title keywords, description, and category tagging`,`Setting up market comparison reports and posting schedule recommendations`],featureSectionTitle:`From product page to sold listing`,featureCardTitles:[`Connects to your selling stack`,`Outputs you can post`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Facebook Marketplace, eBay, Google Sheets, Notion, Canva — Computer plugs into your tools so you can manage listings, track inventory, and close sales in one workflow.`,`Optimized listing titles. Keyword-rich descriptions. Competitive price recommendations. Category and tag suggestions. Photo tips and best posting times.`],capabilitySectionTitle:`Your resale business, on autopilot`,capabilitySectionSubtitle:`Drop a product link, step away, come back to a ready-to-post listing.`,capabilityCards:[{title:`Market Research`,description:`Computer can scan Facebook Marketplace, eBay, and Craigslist for comparable items — and surface the exact price range that sells fastest.`},{title:`Listing Copywriting`,description:`Computer can write titles packed with high-traffic keywords and descriptions that highlight features buyers actually search for.`},{title:`Pricing Strategy`,description:`Computer can analyze sold listings, current competition, and demand signals — then recommend a price that maximizes your margin and sell-through rate.`},{title:`Connect Your Tools`,description:`Computer can read and write to Google Sheets, Notion, eBay, and more — build workflows that track inventory and sales across every platform.`},{title:`Remember & Learn`,description:`Computer can remember your selling categories, preferred margins, and listing style across sessions — so every new listing gets better than the last.`},{title:`Monitor & Alert`,description:`Computer can watch competitor pricing and marketplace trends — set up a monitoring workflow that pings you when it’s time to relist or adjust.`}]});export{t as default};
